import"./chunk-VC46IEJQ.js";var e={group:"free-cities",places:[{id:"braavos",summary:{en:"The northernmost and richest of the Free Cities, founded on a fog-shrouded lagoon by slaves who fled Valyria and hid from the dragonlords for a century. Ruled by an elected Sealord, it is guarded by the Titan, funded by the Iron Bank and served by the Faceless Men of the House of Black and White.",zh:"\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u4E2D\u6700\u5317\u3001\u4E5F\u6700\u5BCC\u6709\u7684\u4E00\u5EA7\uFF0C\u7531\u9003\u79BB\u74E6\u96F7\u5229\u4E9A\u7684\u5974\u96B6\u5EFA\u4E8E\u96FE\u6C14\u7B3C\u7F69\u7684\u6F5F\u6E56\u4E4B\u4E0A\uFF0C\u66FE\u9690\u533F\u767E\u5E74\u800C\u4E0D\u4E3A\u9F99\u738B\u6240\u77E5\u3002\u57CE\u90A6\u7531\u63A8\u9009\u4EA7\u751F\u7684\u6D77\u738B\u7EDF\u6CBB\uFF0C\u6709\u5E03\u62C9\u4F5B\u65AF\u6CF0\u5766\u9547\u5B88\u6D77\u95E8\uFF0C\u94C1\u91D1\u5E93\u4E3A\u5176\u8D22\u6E90\uFF0C\u9ED1\u767D\u4E4B\u9662\u7684\u65E0\u9762\u8005\u4EA6\u6816\u8EAB\u4E8E\u6B64\u3002"},refs:["agot","affc","adwd","twoiaf"],confidence:"high",spoiler:{en:"Arya Stark trains with the Faceless Men here in A Feast for Crows and A Dance with Dragons.",zh:"\u5728\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u548C\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u827E\u8389\u4E9A\xB7\u53F2\u5854\u514B\u5728\u6B64\u968F\u65E0\u9762\u8005\u53D7\u8BAD\u3002"}},{id:"lorath",summary:{en:"The smallest and poorest of the Free Cities, set on a cluster of bleak islands in the Bay of Lorath. Its islands are strewn with the vast stone mazes of a vanished people, and the city lives chiefly from fishing and whaling.",zh:"\u4E5D\u5927\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u4E2D\u6700\u5C0F\u4E5F\u6700\u8D2B\u7A77\u7684\u4E00\u5EA7\uFF0C\u5750\u843D\u4E8E\u6D1B\u62C9\u65AF\u6E7E\u4E2D\u51E0\u5EA7\u8352\u51C9\u7684\u5C9B\u5C7F\u4E0A\u3002\u5C9B\u4E0A\u904D\u5E03\u4E00\u4E2A\u65E9\u5DF2\u6D88\u5931\u7684\u6C11\u65CF\u7559\u4E0B\u7684\u5DE8\u5927\u77F3\u780C\u8FF7\u5BAB\uFF0C\u57CE\u90A6\u4E3B\u8981\u4EE5\u6355\u9C7C\u548C\u6355\u9CB8\u4E3A\u751F\u3002"},refs:["agot","twoiaf"],confidence:"high"},{id:"pentos",summary:{en:"A great trading port on the Narrow Sea, ruled by a prince chosen from the forty families but in practice governed by its rich magisters. It pays tribute to the passing Dothraki rather than fight them, and the exiled Viserys and Daenerys lived here as guests of Magister Illyrio Mopatis.",zh:"\u72ED\u6D77\u4E4B\u6EE8\u7684\u5927\u8D38\u6613\u6E2F\uFF0C\u540D\u4E49\u4E0A\u7531\u4ECE\u56DB\u5341\u4E2A\u5BB6\u65CF\u4E2D\u63A8\u9009\u7684\u4EB2\u738B\u7EDF\u6CBB\uFF0C\u5B9E\u6743\u5374\u63E1\u5728\u5BCC\u6709\u7684\u603B\u7763\u4EEC\u624B\u4E2D\u3002\u6F58\u6258\u65AF\u5B81\u53EF\u5411\u9014\u7ECF\u7684\u591A\u65AF\u62C9\u514B\u4EBA\u7EB3\u8D21\u4E5F\u4E0D\u613F\u5F00\u6218\uFF1B\u6D41\u4EA1\u7684\u97E6\u8D5B\u91CC\u65AF\u4E0E\u4E39\u59AE\u8389\u4E1D\u66FE\u5728\u6B64\u5BC4\u5C45\u4E8E\u4F0A\u5229\u91CC\u6B27\xB7\u83AB\u5E15\u63D0\u65AF\u603B\u7763\u5E9C\u4E2D\u3002"},refs:["agot","adwd","twoiaf"],confidence:"high"},{id:"norvos",summary:{en:"An austere inland city on the Noyne, ruled by bearded priests and split between a high city on a hill and a low city on the river below. Its axe-bearing guards and its great bells are famous, and Prince Doran Martell's wife Mellario came from here.",zh:"\u8BFA\u4F0A\u6CB3\u7554\u4E00\u5EA7\u4E25\u5CFB\u7684\u5185\u9646\u57CE\u90A6\uFF0C\u7531\u84C4\u987B\u7684\u796D\u53F8\u7EDF\u6CBB\uFF0C\u5206\u4E3A\u5C71\u4E18\u4E0A\u7684\u4E0A\u57CE\u4E0E\u6CB3\u8FB9\u7684\u4E0B\u57CE\u3002\u57CE\u4E2D\u624B\u6301\u957F\u65A7\u7684\u536B\u58EB\u548C\u5DE8\u949F\u95FB\u540D\u9050\u8FE9\uFF1B\u591A\u6069\u4EB2\u738B\u9053\u6717\xB7\u9A6C\u6CF0\u5C14\u4E4B\u59BB\u6885\u62C9\u8389\u6B27\u5373\u51FA\u8EAB\u4E8E\u6B64\u3002"},refs:["agot","affc","twoiaf"],confidence:"high"},{id:"qohor",summary:{en:"An eastern Free City on the edge of the great Forest of Qohor, last outpost before the Dothraki sea. Its smiths are said to be the only ones still able to rework Valyrian steel, and its people worship the Black Goat with blood sacrifice.",zh:"\u4F4D\u4E8E\u79D1\u970D\u5C14\u68EE\u6797\u8FB9\u7F18\u7684\u4E1C\u90E8\u81EA\u7531\u8D38\u6613\u57CE\u90A6\uFF0C\u662F\u591A\u65AF\u62C9\u514B\u6D77\u4E4B\u524D\u7684\u6700\u540E\u4E00\u5EA7\u57CE\u5E02\u3002\u636E\u8BF4\u57CE\u4E2D\u94C1\u5320\u662F\u4E16\u4E0A\u4EC5\u5B58\u61C2\u5F97\u91CD\u94F8\u74E6\u96F7\u5229\u4E9A\u94A2\u7684\u4EBA\uFF0C\u5C45\u6C11\u5219\u4EE5\u8840\u796D\u4F9B\u5949\u9ED1\u5C71\u7F8A\u3002"},refs:["agot","asos","twoiaf"],confidence:"high"},{id:"myr",summary:{en:"A port city on a gulf of the Narrow Sea, famous for fine lace, carpets, lenses and its crossbowmen and sellswords. It is endlessly at war with Lys and Tyrosh over the Disputed Lands, and Thoros of Myr, the red priest, came from here.",zh:"\u5750\u843D\u4E8E\u72ED\u6D77\u4E00\u5904\u6D77\u6E7E\u7554\u7684\u6E2F\u53E3\u57CE\u90A6\uFF0C\u4EE5\u7CBE\u7F8E\u857E\u4E1D\u3001\u5730\u6BEF\u3001\u900F\u955C\u4EE5\u53CA\u5F29\u624B\u548C\u4F63\u5175\u95FB\u540D\u3002\u5BC6\u5C14\u4E3A\u4E89\u593A\u4E89\u8BAE\u4E4B\u5730\u4E0E\u91CC\u65AF\u3001\u6CF0\u6D1B\u897F\u5F81\u6218\u4E0D\u4F11\uFF1B\u7EA2\u888D\u50E7\u5BC6\u5C14\u7684\u7D22\u7F57\u65AF\u5373\u51FA\u8EAB\u4E8E\u6B64\u3002"},refs:["agot","acok","twoiaf"],confidence:"high"},{id:"tyrosh",summary:{en:"An island city at the northern end of the Stepstones, ruled by an archon and grown rich on dyes, sweet wines and the sea trade. Tyroshi are known for their brightly dyed hair and beards, and for selling their swords and ships to the highest bidder.",zh:"\u4F4D\u4E8E\u77F3\u9636\u5217\u5C9B\u5317\u7AEF\u7684\u5C9B\u5C7F\u57CE\u90A6\uFF0C\u7531\u6267\u653F\u8005\u7EDF\u6CBB\uFF0C\u9760\u67D3\u6599\u3001\u751C\u9152\u548C\u6D77\u4E0A\u8D38\u6613\u81F4\u5BCC\u3002\u6CF0\u6D1B\u897F\u4EBA\u4EE5\u67D3\u5F97\u4E94\u989C\u516D\u8272\u7684\u5934\u53D1\u548C\u80E1\u987B\u8457\u79F0\uFF0C\u4E5F\u4EE5\u5411\u51FA\u4EF7\u6700\u9AD8\u8005\u51FA\u5356\u5200\u5251\u4E0E\u8239\u53EA\u95FB\u540D\u3002"},refs:["agot","acok","twoiaf"],confidence:"high"},{id:"lys",summary:{en:"An island city south of the Stepstones, renowned for its pleasure houses, its poisons and its pale-haired, violet-eyed people who still carry the blood of Valyria. Its magisters are among the richest slave-traders of the west, and it vies with Myr and Tyrosh over the Disputed Lands.",zh:"\u77F3\u9636\u5217\u5C9B\u4EE5\u5357\u7684\u5C9B\u5C7F\u57CE\u90A6\uFF0C\u4EE5\u6B22\u4E50\u9986\u3001\u6BD2\u836F\u95FB\u540D\uFF0C\u5C45\u6C11\u591A\u4E3A\u6D45\u53D1\u7D2B\u773C\uFF0C\u4ECD\u5E26\u7740\u74E6\u96F7\u5229\u4E9A\u7684\u8840\u7EDF\u3002\u91CC\u65AF\u603B\u7763\u662F\u897F\u65B9\u6700\u5BCC\u6709\u7684\u5974\u96B6\u8D29\u5B50\u4E4B\u4E00\uFF0C\u5E76\u4E0E\u5BC6\u5C14\u3001\u6CF0\u6D1B\u897F\u4E89\u593A\u4E89\u8BAE\u4E4B\u5730\u3002"},houses:["rogare"],refs:["agot","acok","twoiaf"],confidence:"high"},{id:"volantis",summary:{en:"The oldest and proudest of the Free Cities, straddling the mouth of the Rhoyne and joined by the Long Bridge. The old blood of Valyria lives within the Black Walls, three triarchs are elected each year, and five slaves walk its streets for every free man.",zh:"\u6700\u53E4\u8001\u3001\u4E5F\u6700\u9A84\u50B2\u7684\u81EA\u7531\u8D38\u6613\u57CE\u90A6\uFF0C\u6A2A\u8DE8\u6D1B\u6069\u6CB3\u53E3\uFF0C\u4E24\u5CB8\u4EE5\u957F\u6865\u76F8\u8FDE\u3002\u74E6\u96F7\u5229\u4E9A\u65E7\u8840\u8109\u5C45\u4E8E\u9ED1\u5899\u4E4B\u5185\uFF0C\u57CE\u4E2D\u6BCF\u5E74\u9009\u51FA\u4E09\u4F4D\u6267\u653F\u5B98\uFF0C\u8857\u4E0A\u6BCF\u6709\u4E00\u4E2A\u81EA\u7531\u4EBA\u5C31\u6709\u4E94\u4E2A\u5974\u96B6\u3002"},houses:["maegyr","vhassar","paenymion"],refs:["adwd","twoiaf"],confidence:"high"},{id:"selhorys",summary:{en:"A Volantene river town where the Selhoru joins the Rhoyne, the first proper town a traveller meets after the ruined Rhoynish reaches upstream. It is Volantis's northern bulwark on the river, with a garrison, temples and a busy waterfront.",zh:"\u585E\u5C14\u970D\u9C81\u6CB3\u6C47\u5165\u6D1B\u6069\u6CB3\u5904\u7684\u74E6\u5170\u63D0\u65AF\u6CB3\u7554\u57CE\u9547\uFF0C\u4E5F\u662F\u65C5\u4EBA\u7A7F\u8FC7\u4E0A\u6E38\u6D1B\u4F0A\u62FF\u5E9F\u589F\u540E\u9047\u5230\u7684\u7B2C\u4E00\u5EA7\u50CF\u6837\u7684\u57CE\u9547\u3002\u5B83\u662F\u74E6\u5170\u63D0\u65AF\u5728\u6CB3\u4E0A\u7684\u5317\u65B9\u5C4F\u969C\uFF0C\u57CE\u4E2D\u9A7B\u6709\u5B88\u519B\uFF0C\u795E\u5E99\u6797\u7ACB\uFF0C\u7801\u5934\u7E41\u5FD9\u3002"},refs:["adwd","twoiaf"],confidence:"medium",spoiler:{en:"In A Dance with Dragons Tyrion is seized in a Selhorys brothel by Jorah Mormont.",zh:"\u5728\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u63D0\u5229\u6602\u5728\u585E\u5C14\u970D\u5229\u65AF\u7684\u4E00\u5BB6\u5993\u9662\u88AB\u4E54\u62C9\xB7\u83AB\u5C14\u8499\u6293\u8D70\u3002"}},{id:"rhoyne",kind:"river",region:"free-cities",at:[1036,1100],rank:4,names:{en:"The Rhoyne",zh:"\u6D1B\u6069\u6CB3"},alt:["Mother Rhoyne","\u6D1B\u6069\u6BCD\u4EB2","\u7F57\u4F0A\u62FF\u6CB3"],summary:{en:"The greatest river of the west of Essos, called Mother Rhoyne by the Rhoynar who once built a civilisation of river cities along her banks. Fed by many tributaries, she runs south for hundreds of miles to the sea at Volantis.",zh:"\u5384\u7D22\u65AF\u897F\u90E8\u6700\u5927\u7684\u6CB3\u6D41\uFF0C\u6614\u65E5\u6CBF\u5CB8\u5EFA\u8D77\u4E00\u8FDE\u4E32\u6CB3\u7554\u57CE\u5E02\u7684\u6D1B\u4F0A\u62FF\u4EBA\u5C0A\u79F0\u5979\u4E3A\u201C\u6D1B\u6069\u6BCD\u4EB2\u201D\u3002\u5979\u6C47\u805A\u4F17\u591A\u652F\u6D41\uFF0C\u5411\u5357\u5954\u6D41\u6570\u767E\u82F1\u91CC\uFF0C\u5728\u74E6\u5170\u63D0\u65AF\u5165\u6D77\u3002"},refs:["adwd","twoiaf","maps"],confidence:"high"},{id:"upper-rhoyne",kind:"river",region:"free-cities",at:[990,740],rank:2,names:{en:"The Upper Rhoyne",zh:"\u4E0A\u6D1B\u6069\u6CB3"},alt:["Rhoyne headwaters"],summary:{en:"The northern reach of the Rhoyne, flowing down from the Hills of Norvos past the Forest of Qohor. The ruins of Ny Sar stand on its banks.",zh:"\u6D1B\u6069\u6CB3\u7684\u5317\u6BB5\uFF0C\u81EA\u8BFA\u4F5B\u65AF\u4E18\u9675\u6D41\u4E0B\uFF0C\u7ECF\u8FC7\u79D1\u970D\u5C14\u68EE\u6797\u3002\u5C3C\xB7\u8428\u7684\u5E9F\u589F\u5C31\u77D7\u7ACB\u5728\u5B83\u7684\u5CB8\u8FB9\u3002"},refs:["twoiaf","maps"],confidence:"medium"},{id:"little-rhoyne",kind:"river",region:"free-cities",at:[1052,800],rank:2,names:{en:"The Little Rhoyne",zh:"\u5C0F\u6D1B\u6069\u6CB3"},summary:{en:"An eastern tributary that flows past Qohor and through its forest before joining the Rhoyne. It gives Qohor its river link to the south.",zh:"\u6D1B\u6069\u6CB3\u7684\u4E00\u6761\u4E1C\u90E8\u652F\u6D41\uFF0C\u6D41\u7ECF\u79D1\u970D\u5C14\u57CE\u53CA\u5176\u68EE\u6797\u540E\u6C47\u5165\u6D1B\u6069\u6CB3\uFF0C\u4E3A\u79D1\u970D\u5C14\u63D0\u4F9B\u4E86\u901A\u5F80\u5357\u65B9\u7684\u6C34\u8DEF\u3002"},refs:["twoiaf","maps"],confidence:"medium"},{id:"noyne",kind:"river",region:"free-cities",at:[946,790],rank:2,names:{en:"The Noyne",zh:"\u8BFA\u4F0A\u6CB3"},summary:{en:"A western tributary of the Rhoyne that flows past Norvos and meets the main river at the ruins of Ghoyan Drohe. River traffic from Pentos and Norvos joins the Rhoyne here.",zh:"\u6D1B\u6069\u6CB3\u7684\u897F\u90E8\u652F\u6D41\uFF0C\u6D41\u7ECF\u8BFA\u4F5B\u65AF\uFF0C\u5728\u6208\u5EF6\xB7\u5353\u8D6B\u5E9F\u589F\u5904\u6C47\u5165\u5E72\u6D41\u3002\u6765\u81EA\u6F58\u6258\u65AF\u548C\u8BFA\u4F5B\u65AF\u65B9\u5411\u7684\u8239\u53EA\u7531\u6B64\u8FDB\u5165\u6D1B\u6069\u6CB3\u3002"},refs:["adwd","twoiaf","maps"],confidence:"medium"},{id:"qhoyne",kind:"river",region:"free-cities",at:[1050,908],rank:2,names:{en:"The Qhoyne",zh:"\u514B\u970D\u4F0A\u6CB3"},summary:{en:"An eastern tributary flowing out of the plains towards the Rhoyne, which it joins at the ruins of Ar Noy.",zh:"\u4E00\u6761\u53D1\u6E90\u4E8E\u4E1C\u65B9\u5E73\u539F\u7684\u652F\u6D41\uFF0C\u5411\u897F\u6D41\u5165\u6D1B\u6069\u6CB3\uFF0C\u4EA4\u6C47\u5904\u4FBF\u662F\u963F\xB7\u8BFA\u4F0A\u7684\u5E9F\u589F\u3002"},refs:["twoiaf","maps"],confidence:"medium"},{id:"lhorulu",kind:"river",region:"free-cities",at:[1036,974],rank:1,names:{en:"The Lhorulu",zh:"\u6D1B\u9C81\u9C81\u6CB3"},summary:{en:"A lesser eastern tributary that meets the Rhoyne near the drowned ruins of Chroyane, in the fog of the Sorrows.",zh:"\u4E00\u6761\u8F83\u5C0F\u7684\u4E1C\u90E8\u652F\u6D41\uFF0C\u5728\u54C0\u4F24\u4E4B\u5730\u7684\u8FF7\u96FE\u4E2D\u3001\u514B\u7F57\u626C\u6C89\u6CA1\u5E9F\u589F\u9644\u8FD1\u6C47\u5165\u6D1B\u6069\u6CB3\u3002"},refs:["twoiaf","maps"],confidence:"low"},{id:"selhoru",kind:"river",region:"free-cities",at:[1052,1054],rank:1,names:{en:"The Selhoru",zh:"\u585E\u5C14\u970D\u9C81\u6CB3"},summary:{en:"An eastern tributary that joins the Rhoyne at the Volantene town of Selhorys, which takes its name from the river.",zh:"\u6D1B\u6069\u6CB3\u7684\u4E1C\u90E8\u652F\u6D41\uFF0C\u5728\u74E6\u5170\u63D0\u65AF\u6CBB\u4E0B\u7684\u585E\u5C14\u970D\u5229\u65AF\u9547\u6C47\u5165\u5E72\u6D41\uFF0C\u8BE5\u9547\u5373\u56E0\u6B64\u6CB3\u5F97\u540D\u3002"},refs:["twoiaf","maps"],confidence:"medium"},{id:"sorrows",kind:"swamp",region:"free-cities",at:[1014,996],rank:2,names:{en:"The Sorrows",zh:"\u54C0\u4F24\u4E4B\u5730"},alt:["Shrouded Lord"],summary:{en:"A stretch of the Rhoyne around ruined Chroyane where a thick, unnatural fog never lifts. Rivermen say it is the curse of Garin the Great, and they fear the stone men \u2014 victims of greyscale \u2014 who lurk in the ruins under the rule of the Shrouded Lord.",zh:"\u6D1B\u6069\u6CB3\u5728\u514B\u7F57\u626C\u5E9F\u589F\u4E00\u5E26\u7684\u6CB3\u6BB5\uFF0C\u7EC8\u5E74\u7B3C\u7F69\u7740\u4E00\u5C42\u6D53\u91CD\u800C\u8BE1\u5F02\u7684\u8FF7\u96FE\u3002\u8239\u592B\u4EEC\u8BF4\u8FD9\u662F\u4F1F\u5927\u7684\u52A0\u6797\u7559\u4E0B\u7684\u8BC5\u5492\uFF0C\u5E76\u754F\u60E7\u6F5C\u4F0F\u5728\u5E9F\u589F\u4E2D\u3001\u542C\u547D\u4E8E\u201C\u88F9\u5E03\u4E4B\u738B\u201D\u7684\u77F3\u4EBA\u2014\u2014\u90A3\u4E9B\u67D3\u4E0A\u7070\u9CDE\u75C5\u7684\u53EF\u601C\u4EBA\u3002"},refs:["adwd","twoiaf"],confidence:"high"},{id:"dagger-lake",kind:"lake",region:"free-cities",at:[1126,868],rank:2,names:{en:"Dagger Lake",zh:"\u5315\u9996\u6E56"},summary:{en:"A long lake in the lands east of the Rhoyne, notorious in the histories as a haunt of lake pirates who preyed on river traffic.",zh:"\u6D1B\u6069\u6CB3\u4EE5\u4E1C\u5730\u533A\u7684\u4E00\u5EA7\u72ED\u957F\u6E56\u6CCA\uFF0C\u5728\u53F2\u4E66\u4E2D\u4EE5\u6E56\u76D7\u51FA\u6CA1\u3001\u52AB\u63A0\u5F80\u6765\u8239\u53EA\u800C\u8457\u79F0\u3002"},refs:["twoiaf","maps"],confidence:"low"},{id:"ny-sar",kind:"ruin",region:"free-cities",at:[986,712],rank:2,names:{en:"Ny Sar",zh:"\u5C3C\xB7\u8428"},alt:["Nysar"],summary:{en:"A ruined Rhoynish city on the upper Rhoyne, remembered as the city of Princess Nymeria. When Valyria destroyed the Rhoynar, Nymeria led her people from here on the long flight that ended in Dorne.",zh:"\u4E0A\u6D1B\u6069\u6CB3\u7554\u4E00\u5EA7\u6D1B\u4F0A\u62FF\u5E9F\u57CE\uFF0C\u88AB\u4EBA\u4EEC\u8BB0\u4F5C\u5948\u6885\u8389\u4E9A\u516C\u4E3B\u7684\u57CE\u5E02\u3002\u74E6\u96F7\u5229\u4E9A\u6467\u6BC1\u6D1B\u4F0A\u62FF\u8BF8\u57CE\u4E4B\u540E\uFF0C\u5948\u6885\u8389\u4E9A\u7531\u6B64\u7387\u9886\u65CF\u4EBA\u8E0F\u4E0A\u6F2B\u957F\u7684\u6D41\u4EA1\u4E4B\u8DEF\uFF0C\u6700\u7EC8\u5728\u591A\u6069\u843D\u811A\u3002"},houses:[],refs:["adwd","twoiaf"],confidence:"medium"},{id:"ghoyan-drohe",kind:"ruin",region:"free-cities",at:[982,870],rank:2,names:{en:"Ghoyan Drohe",zh:"\u6208\u5EF6\xB7\u5353\u8D6B"},summary:{en:"The ruins of a Rhoynish city where the Noyne meets the Rhoyne, burned by the dragons in the wars against Valyria. Travellers from Pentos take boat here to go downriver.",zh:"\u8BFA\u4F0A\u6CB3\u4E0E\u6D1B\u6069\u6CB3\u4EA4\u6C47\u5904\u7684\u4E00\u5EA7\u6D1B\u4F0A\u62FF\u57CE\u5E02\u5E9F\u589F\uFF0C\u6BC1\u4E8E\u5BF9\u6297\u74E6\u96F7\u5229\u4E9A\u6218\u4E89\u4E2D\u7684\u9F99\u7130\u3002\u4ECE\u6F58\u6258\u65AF\u6765\u7684\u65C5\u4EBA\u5E38\u5728\u8FD9\u91CC\u767B\u8239\u987A\u6D41\u800C\u4E0B\u3002"},refs:["adwd","twoiaf"],confidence:"high",spoiler:{en:"Tyrion joins Griff's party on the Shy Maid here in A Dance with Dragons.",zh:"\u5728\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u63D0\u5229\u6602\u5728\u6B64\u767B\u4E0A\u201C\u7F9E\u602F\u5C11\u5973\u53F7\u201D\uFF0C\u52A0\u5165\u683C\u91CC\u592B\u4E00\u884C\u3002"}},{id:"sar-mell",kind:"ruin",region:"free-cities",at:[986,902],rank:1,names:{en:"Sar Mell",zh:"\u8428\xB7\u6885\u5C14"},summary:{en:"One of the lost cities of the Rhoynar, overrun when Valyria broke their confederation. Its site on the river is given only roughly here.",zh:"\u6D1B\u4F0A\u62FF\u4EBA\u5DF2\u5931\u843D\u7684\u57CE\u5E02\u4E4B\u4E00\uFF0C\u5728\u74E6\u96F7\u5229\u4E9A\u51FB\u6E83\u6D1B\u4F0A\u62FF\u8BF8\u57CE\u8054\u76DF\u65F6\u9677\u843D\u3002\u6B64\u5904\u6807\u6CE8\u7684\u6CB3\u7554\u4F4D\u7F6E\u4EC5\u4E3A\u5927\u81F4\u63A8\u6D4B\u3002"},refs:["twoiaf"],confidence:"low"},{id:"ar-noy",kind:"ruin",region:"free-cities",at:[992,930],rank:2,names:{en:"Ar Noy",zh:"\u963F\xB7\u8BFA\u4F0A"},summary:{en:"A ruined Rhoynish city at the meeting of the Qhoyne and the Rhoyne. Like its sisters it fell in the wars with Valyria, and only broken stone remains.",zh:"\u514B\u970D\u4F0A\u6CB3\u4E0E\u6D1B\u6069\u6CB3\u4EA4\u6C47\u5904\u7684\u4E00\u5EA7\u6D1B\u4F0A\u62FF\u57CE\u5E02\u5E9F\u589F\u3002\u5B83\u548C\u59CA\u59B9\u57CE\u5E02\u4E00\u6837\u9677\u843D\u4E8E\u4E0E\u74E6\u96F7\u5229\u4E9A\u7684\u6218\u4E89\uFF0C\u5982\u4ECA\u53EA\u4F59\u65AD\u58C1\u6B8B\u57A3\u3002"},refs:["adwd","twoiaf"],confidence:"medium"},{id:"chroyane",kind:"ruin",region:"free-cities",at:[1006,980],rank:3,names:{en:"Chroyane",zh:"\u514B\u7F57\u626C"},alt:["Festival city"],summary:{en:'Once the "festival city" of the Rhoynar, home of Garin the Great, who rose against Valyria and was destroyed with his army. Its drowned ruins now lie half-sunk in the Rhoyne amid the fogs of the Sorrows.',zh:"\u6614\u65E5\u6D1B\u4F0A\u62FF\u4EBA\u7684\u201C\u8282\u5E86\u4E4B\u57CE\u201D\uFF0C\u4E5F\u662F\u4F1F\u5927\u7684\u52A0\u6797\u7684\u6545\u4E61\uFF1B\u52A0\u6797\u8D77\u5175\u53CD\u6297\u74E6\u96F7\u5229\u4E9A\uFF0C\u6700\u7EC8\u4E0E\u5927\u519B\u4E00\u540C\u8986\u706D\u3002\u5982\u4ECA\u5B83\u7684\u5E9F\u589F\u534A\u6CA1\u4E8E\u6D1B\u6069\u6CB3\u4E2D\uFF0C\u9690\u5728\u54C0\u4F24\u4E4B\u5730\u7684\u8FF7\u96FE\u91CC\u3002"},refs:["adwd","twoiaf"],confidence:"high"},{id:"bridge-of-dream",kind:"landmark",region:"free-cities",at:[1e3,986],rank:1,names:{en:"Bridge of Dream",zh:"\u68A6\u4E4B\u6865"},summary:{en:"A broken stone bridge spanning the Rhoyne in the ruins of Chroyane. Boats must pass beneath it, and the stone men of the Sorrows are said to drop from it onto passing decks.",zh:"\u514B\u7F57\u626C\u5E9F\u589F\u4E2D\u6A2A\u8DE8\u6D1B\u6069\u6CB3\u7684\u4E00\u5EA7\u6B8B\u7834\u77F3\u6865\u3002\u8FC7\u5F80\u8239\u53EA\u5FC5\u987B\u4ECE\u6865\u4E0B\u7A7F\u8FC7\uFF0C\u636E\u8BF4\u54C0\u4F24\u4E4B\u5730\u7684\u77F3\u4EBA\u4F1A\u4ECE\u6865\u4E0A\u8DF3\u843D\u5230\u7532\u677F\u4E0A\u3002"},refs:["adwd"],confidence:"medium",spoiler:{en:"Stone men attack the Shy Maid beneath the bridge; Tyrion is dragged into the river and afterwards fears he has caught greyscale.",zh:"\u77F3\u4EBA\u5728\u6865\u4E0B\u88AD\u51FB\u201C\u7F9E\u602F\u5C11\u5973\u53F7\u201D\uFF0C\u63D0\u5229\u6602\u88AB\u62D6\u5165\u6CB3\u4E2D\uFF0C\u4ECE\u6B64\u62C5\u5FC3\u81EA\u5DF1\u67D3\u4E0A\u4E86\u7070\u9CDE\u75C5\u3002"}},{id:"palace-of-love",kind:"ruin",region:"free-cities",at:[1012,974],rank:1,names:{en:"Palace of Love",zh:"\u7231\u4E4B\u5BAB"},summary:{en:"A ruined palace in drowned Chroyane, glimpsed through the fog by river travellers. Its broken halls recall the city's lost splendour.",zh:"\u6C89\u6CA1\u7684\u514B\u7F57\u626C\u57CE\u4E2D\u4E00\u5EA7\u5BAB\u6BBF\u7684\u5E9F\u589F\uFF0C\u6CB3\u4E0A\u65C5\u4EBA\u53EA\u80FD\u900F\u8FC7\u8FF7\u96FE\u7AA5\u89C1\u5176\u8F6E\u5ED3\u3002\u6B8B\u7834\u7684\u5385\u5802\u4EE4\u4EBA\u8FFD\u60F3\u8FD9\u5EA7\u57CE\u5E02\u6614\u65E5\u7684\u7E41\u534E\u3002"},refs:["adwd"],confidence:"medium"},{id:"valysar",kind:"town",region:"free-cities",at:[1044,1118],rank:2,names:{en:"Valysar",zh:"\u74E6\u5229\u8428"},summary:{en:"A Volantene town on the lower Rhoyne between Selhorys and Volon Therys. Its river garrisons and boats tie the towns of the river to the mother city.",zh:"\u6D1B\u6069\u6CB3\u4E0B\u6E38\u7684\u4E00\u5EA7\u74E6\u5170\u63D0\u65AF\u57CE\u9547\uFF0C\u4F4D\u4E8E\u585E\u5C14\u970D\u5229\u65AF\u4E0E\u6C83\u9686\xB7\u585E\u5229\u65AF\u4E4B\u95F4\u3002\u6CB3\u4E0A\u7684\u9A7B\u519B\u548C\u8239\u53EA\u5C06\u6CBF\u6CB3\u8BF8\u9547\u4E0E\u6BCD\u57CE\u7D27\u5BC6\u76F8\u8FDE\u3002"},refs:["adwd","twoiaf"],confidence:"medium"},{id:"volon-therys",kind:"town",region:"free-cities",at:[1050,1166],rank:2,names:{en:"Volon Therys",zh:"\u6C83\u9686\xB7\u585E\u5229\u65AF"},summary:{en:"The last Volantene town on the Rhoyne before Volantis itself, a short way upriver from the sea. Travellers heading for the city by boat pass it on their final day.",zh:"\u6D1B\u6069\u6CB3\u4E0A\u5230\u8FBE\u74E6\u5170\u63D0\u65AF\u672C\u57CE\u524D\u7684\u6700\u540E\u4E00\u5EA7\u74E6\u5170\u63D0\u65AF\u57CE\u9547\uFF0C\u8DDD\u5165\u6D77\u53E3\u4E0D\u8FDC\u3002\u4E58\u8239\u524D\u5F80\u74E6\u5170\u63D0\u65AF\u7684\u65C5\u4EBA\u4F1A\u5728\u822A\u7A0B\u7684\u6700\u540E\u4E00\u5929\u7ECF\u8FC7\u8FD9\u91CC\u3002"},refs:["adwd","twoiaf"],confidence:"medium"},{id:"forest-of-qohor",kind:"forest",region:"free-cities",at:[1020,760],rank:3,names:{en:"The Forest of Qohor",zh:"\u79D1\u970D\u5C14\u68EE\u6797"},summary:{en:"A vast forest stretching west of Qohor, the largest in western Essos. Khal Drogo's khalasar crossed it on the way east, and the Qohorik draw their timber and furs from its depths.",zh:"\u79D1\u970D\u5C14\u4EE5\u897F\u7684\u4E00\u7247\u5E7F\u88A4\u68EE\u6797\uFF0C\u662F\u5384\u7D22\u65AF\u897F\u90E8\u6700\u5927\u7684\u6797\u5730\u3002\u5353\u6208\u5361\u5965\u7684\u5361\u62C9\u8428\u4E1C\u884C\u65F6\u66FE\u7A7F\u8D8A\u6B64\u6797\uFF0C\u79D1\u970D\u5C14\u4EBA\u4E5F\u4ECE\u6797\u4E2D\u53D6\u5F97\u6728\u6750\u4E0E\u6BDB\u76AE\u3002"},refs:["agot","twoiaf","maps"],confidence:"high"},{id:"hills-of-norvos",kind:"mountain",region:"free-cities",at:[940,690],rank:2,names:{en:"Hills of Norvos",zh:"\u8BFA\u4F5B\u65AF\u4E18\u9675"},summary:{en:"Rolling uplands north of Norvos where the Noyne and the upper Rhoyne take their rise. They formed part of the ancient homeland of the Andals.",zh:"\u8BFA\u4F5B\u65AF\u4EE5\u5317\u7684\u8D77\u4F0F\u9AD8\u5730\uFF0C\u8BFA\u4F0A\u6CB3\u4E0E\u4E0A\u6D1B\u6069\u6CB3\u7686\u53D1\u6E90\u4E8E\u6B64\uFF0C\u66FE\u662F\u5B89\u8FBE\u5C14\u4EBA\u53E4\u8001\u6545\u571F\u7684\u4E00\u90E8\u5206\u3002"},refs:["twoiaf","maps"],confidence:"medium"},{id:"hills-of-andalos",kind:"mountain",region:"free-cities",at:[830,740],rank:2,names:{en:"Hills of Andalos",zh:"\u5B89\u8FBE\u6D1B\u65AF\u4E18\u9675"},alt:["Andalos","\u5B89\u8FBE\u6D1B\u65AF"],summary:{en:"Hill country in the lands between Braavos and Pentos, once part of Andalos, the homeland of the Andals. The Faith of the Seven holds that the Seven walked these hills, and from here the Andals crossed the sea to conquer Westeros.",zh:"\u5E03\u62C9\u4F5B\u65AF\u4E0E\u6F58\u6258\u65AF\u4E4B\u95F4\u7684\u4E18\u9675\u5730\u5E26\uFF0C\u6614\u4E3A\u5B89\u8FBE\u5C14\u4EBA\u7684\u6545\u571F\u5B89\u8FBE\u6D1B\u65AF\u7684\u4E00\u90E8\u5206\u3002\u4E03\u795E\u4FE1\u4EF0\u8BA4\u4E3A\u4E03\u795E\u66FE\u884C\u8D70\u4E8E\u8FD9\u7247\u5C71\u4E18\uFF0C\u5B89\u8FBE\u5C14\u4EBA\u4E5F\u6B63\u662F\u7531\u6B64\u6E21\u6D77\u5F81\u670D\u7EF4\u65AF\u7279\u6D1B\u3002"},refs:["agot","twoiaf"],confidence:"medium"},{id:"the-axe",kind:"landmark",region:"free-cities",at:[882,522],rank:2,names:{en:"The Axe",zh:"\u65A7\u5934\u534A\u5C9B"},summary:{en:"A rugged peninsula jutting north into the Shivering Sea west of the Bay of Lorath, at the northern edge of the old Andal lands.",zh:"\u4F4D\u4E8E\u6D1B\u62C9\u65AF\u6E7E\u4EE5\u897F\u3001\u5411\u5317\u4F38\u5165\u98A4\u6296\u6D77\u7684\u4E00\u5EA7\u5D0E\u5C96\u534A\u5C9B\uFF0C\u5730\u5904\u53E4\u4EE3\u5B89\u8FBE\u5C14\u4EBA\u9886\u571F\u7684\u5317\u7F18\u3002"},refs:["twoiaf","maps"],confidence:"medium"},{id:"velvet-hills",kind:"mountain",region:"free-cities",at:[920,910],rank:2,names:{en:"Velvet Hills",zh:"\u5929\u9E45\u7ED2\u4E18\u9675"},summary:{en:"Soft, green hills in the Pentoshi hinterland between the coast and the Rhoyne. Travellers going overland from Pentos to the river cross them on the way to Ghoyan Drohe.",zh:"\u6F58\u6258\u65AF\u8179\u5730\u4E2D\u3001\u6D77\u5CB8\u4E0E\u6D1B\u6069\u6CB3\u4E4B\u95F4\u4E00\u7247\u67D4\u7F13\u7684\u7EFF\u8272\u4E18\u9675\u3002\u4ECE\u6F58\u6258\u65AF\u8D70\u9646\u8DEF\u524D\u5F80\u6D1B\u6069\u6CB3\u7684\u65C5\u4EBA\uFF0C\u4F1A\u7A7F\u8FC7\u8FD9\u91CC\u62B5\u8FBE\u6208\u5EF6\xB7\u5353\u8D6B\u3002"},refs:["adwd","twoiaf"],confidence:"medium"},{id:"flatlands",kind:"landmark",region:"free-cities",at:[860,840],rank:2,names:{en:"The Flatlands",zh:"\u5E73\u5730"},alt:["Pentoshi plains","\u5E73\u539F"],summary:{en:'The level grasslands behind Pentos. Here the Dothraki khalasars camp when they come to collect their "gifts", and Daenerys was wed to Khal Drogo outside the city walls.',zh:"\u6F58\u6258\u65AF\u57CE\u540E\u7684\u4E00\u7247\u5E73\u5766\u8349\u539F\u3002\u591A\u65AF\u62C9\u514B\u5361\u62C9\u8428\u524D\u6765\u6536\u53D6\u201C\u793C\u7269\u201D\u65F6\u4FBF\u5728\u6B64\u624E\u8425\uFF0C\u4E39\u59AE\u8389\u4E1D\u4E0E\u5353\u6208\u5361\u5965\u7684\u5A5A\u793C\u4E5F\u5728\u57CE\u5899\u5916\u7684\u8FD9\u7247\u571F\u5730\u4E0A\u4E3E\u884C\u3002"},refs:["agot","twoiaf"],confidence:"medium"},{id:"golden-fields",kind:"landmark",region:"free-cities",at:[1110,940],rank:2,names:{en:"The Golden Fields",zh:"\u91D1\u8272\u539F\u91CE"},summary:{en:"Rich grain lands east of the Rhoyne, between its eastern tributaries. They fed the Rhoynish cities of old and lie on the margin of the Dothraki sea.",zh:"\u6D1B\u6069\u6CB3\u4EE5\u4E1C\u3001\u51E0\u6761\u4E1C\u90E8\u652F\u6D41\u4E4B\u95F4\u7684\u5BCC\u9976\u8C37\u5730\uFF0C\u6614\u65E5\u4F9B\u517B\u7740\u6D1B\u4F0A\u62FF\u8BF8\u57CE\uFF0C\u5982\u4ECA\u5730\u5904\u591A\u65AF\u62C9\u514B\u6D77\u7684\u8FB9\u7F18\u3002"},refs:["twoiaf","maps"],confidence:"low"},{id:"disputed-lands",kind:"landmark",region:"free-cities",at:[846,1150],rank:3,names:{en:"The Disputed Lands",zh:"\u4E89\u8BAE\u4E4B\u5730"},summary:{en:"Contested borderlands between Myr, Lys and Tyrosh, fought over for centuries and changing hands with every alliance. Sellsword companies, the Golden Company among them, find steady employment in their wars.",zh:"\u5BC6\u5C14\u3001\u91CC\u65AF\u4E0E\u6CF0\u6D1B\u897F\u4E4B\u95F4\u7684\u8FB9\u5883\u5730\u5E26\uFF0C\u6570\u767E\u5E74\u6765\u4E89\u6218\u4E0D\u4F11\uFF0C\u968F\u6BCF\u4E00\u6B21\u7ED3\u76DF\u53D8\u6362\u800C\u6613\u624B\u3002\u4F63\u5175\u56E2\u2014\u2014\u5305\u62EC\u9EC4\u91D1\u56E2\u2014\u2014\u5728\u8FD9\u91CC\u7684\u6218\u4E8B\u4E2D\u603B\u80FD\u627E\u5230\u5DEE\u4E8B\u3002"},refs:["agot","adwd","twoiaf"],confidence:"high"},{id:"orange-shore",kind:"landmark",region:"free-cities",at:[960,1212],rank:2,names:{en:"The Orange Shore",zh:"\u6A59\u8272\u6D77\u5CB8"},summary:{en:"The warm southern coast running west from the mouth of the Rhoyne towards the Disputed Lands, part of the Volantene sphere and known for its orange groves.",zh:"\u81EA\u6D1B\u6069\u6CB3\u53E3\u5411\u897F\u5EF6\u4F38\u81F3\u4E89\u8BAE\u4E4B\u5730\u7684\u6E29\u6696\u5357\u90E8\u6D77\u5CB8\uFF0C\u5C5E\u74E6\u5170\u63D0\u65AF\u52BF\u529B\u8303\u56F4\uFF0C\u4EE5\u6A59\u6811\u6797\u95FB\u540D\u3002"},refs:["adwd","maps"],confidence:"low"},{id:"demon-road",kind:"landmark",region:"valyria",at:[1112,1228],rank:2,names:{en:"The Demon Road",zh:"\u6076\u9B54\u4E4B\u8DEF"},summary:{en:"The old Valyrian road leading east from Volantis across the neck of the Valyrian peninsula towards Mantarys and Slaver's Bay. Its name comes from the dangers of the lands it crosses, and travellers prefer the sea.",zh:"\u4E00\u6761\u53E4\u8001\u7684\u74E6\u96F7\u5229\u4E9A\u5927\u9053\uFF0C\u81EA\u74E6\u5170\u63D0\u65AF\u5411\u4E1C\u7A7F\u8FC7\u74E6\u96F7\u5229\u4E9A\u534A\u5C9B\u7684\u9888\u90E8\uFF0C\u901A\u5F80\u66FC\u5854\u91CC\u65AF\u4E0E\u5974\u96B6\u6E7E\u3002\u6B64\u8DEF\u56E0\u6CBF\u9014\u51F6\u9669\u800C\u5F97\u540D\uFF0C\u65C5\u4EBA\u591A\u5B81\u613F\u8D70\u6D77\u8DEF\u3002"},refs:["adwd","twoiaf"],confidence:"medium"},{id:"battle-of-qohor",kind:"battle",region:"free-cities",at:[1092,788],rank:2,names:{en:"The Three Thousand of Qohor",zh:"\u79D1\u970D\u5C14\u7684\u4E09\u5343\u52C7\u58EB"},alt:["Battle of Qohor","\u79D1\u970D\u5C14\u4E4B\u6218"],summary:{en:"Before the gates of Qohor, three thousand Unsullied hired by the city stood against a Dothraki horde many times their number and broke charge after charge. The Dothraki who survived cut off their braids in shame, and the tale made the Unsullied famous.",zh:"\u5728\u79D1\u970D\u5C14\u57CE\u95E8\u524D\uFF0C\u57CE\u90A6\u96C7\u6765\u7684\u4E09\u5343\u540D\u65E0\u57A2\u8005\u8FCE\u6218\u6570\u500D\u4E8E\u5DF1\u7684\u591A\u65AF\u62C9\u514B\u5927\u519B\uFF0C\u4E00\u6B21\u53C8\u4E00\u6B21\u51FB\u9000\u51B2\u950B\u3002\u5E78\u5B58\u7684\u591A\u65AF\u62C9\u514B\u4EBA\u7F9E\u6127\u5730\u5272\u6389\u4E86\u8FAB\u5B50\uFF0C\u65E0\u57A2\u8005\u4E5F\u56E0\u6B64\u5F79\u58F0\u540D\u8FDC\u626C\u3002"},refs:["asos","twoiaf"],confidence:"medium"},{id:"bay-of-lorath",kind:"bay",region:"free-cities",at:[960,560],rank:2,names:{en:"Bay of Lorath",zh:"\u6D1B\u62C9\u65AF\u6E7E"},summary:{en:"The sheltered bay on Essos's northern coast in which the Isles of Lorath lie, opening onto the Shivering Sea.",zh:"\u5384\u7D22\u65AF\u5317\u5CB8\u4E00\u5904\u907F\u98CE\u7684\u6D77\u6E7E\uFF0C\u6D1B\u62C9\u65AF\u7FA4\u5C9B\u5C31\u5750\u843D\u5176\u4E2D\uFF0C\u6E7E\u53E3\u671D\u5411\u98A4\u6296\u6D77\u3002"},refs:["twoiaf","maps"],confidence:"high"},{id:"isles-of-lorath",kind:"island",region:"free-cities",at:[946,534],rank:1,names:{en:"Isles of Lorath",zh:"\u6D1B\u62C9\u65AF\u7FA4\u5C9B"},summary:{en:"A small group of rocky islands in the Bay of Lorath, the largest of which holds the Free City of Lorath. Earlier peoples left mazes and ruins on all of them.",zh:"\u6D1B\u62C9\u65AF\u6E7E\u4E2D\u7684\u4E00\u5C0F\u7FA4\u5CA9\u77F3\u5C9B\u5C7F\uFF0C\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u6D1B\u62C9\u65AF\u5750\u843D\u5728\u5176\u4E2D\u6700\u5927\u7684\u4E00\u5EA7\u5C9B\u4E0A\u3002\u65E9\u5148\u7684\u6C11\u65CF\u5728\u5404\u5C9B\u4E0A\u90FD\u7559\u4E0B\u4E86\u8FF7\u5BAB\u4E0E\u9057\u8FF9\u3002"},refs:["twoiaf","maps"],confidence:"high"},{id:"lorath-mazes",kind:"ruin",region:"free-cities",at:[998,518],rank:1,names:{en:"Mazes of the Mazemakers",zh:"\u8FF7\u5BAB\u5EFA\u9020\u8005\u7684\u8FF7\u5BAB"},alt:["Mazemakers","\u8FF7\u5BAB\u5EFA\u9020\u8005"],summary:{en:"Great stone labyrinths raised on the Isles of Lorath by the mysterious Mazemakers, a people who vanished long before the Andals or Valyrians came. No one knows their purpose.",zh:"\u795E\u79D8\u7684\u201C\u8FF7\u5BAB\u5EFA\u9020\u8005\u201D\u5728\u6D1B\u62C9\u65AF\u7FA4\u5C9B\u4E0A\u4FEE\u7B51\u7684\u5DE8\u5927\u77F3\u780C\u8FF7\u5BAB\uFF1B\u8FD9\u4E2A\u6C11\u65CF\u65E9\u5728\u5B89\u8FBE\u5C14\u4EBA\u4E0E\u74E6\u96F7\u5229\u4E9A\u4EBA\u5230\u6765\u4E4B\u524D\u4FBF\u5DF2\u6D88\u5931\u3002\u65E0\u4EBA\u77E5\u6653\u8FD9\u4E9B\u8FF7\u5BAB\u7684\u7528\u9014\u3002"},refs:["twoiaf"],confidence:"medium"},{id:"stepstones",kind:"island",region:"free-cities",at:[704,1208],rank:3,names:{en:"The Stepstones",zh:"\u77F3\u9636\u5217\u5C9B"},summary:{en:"A broken chain of islands strung between Dorne's Broken Arm and Essos \u2014 said to be the remnant of an ancient land bridge, the Arm of Dorne. Long a nest of pirates and a battleground of the Free Cities, they were also where the War of the Ninepenny Kings was fought.",zh:"\u4E00\u4E32\u6563\u843D\u4E8E\u591A\u6069\u65AD\u81C2\u89D2\u4E0E\u5384\u7D22\u65AF\u4E4B\u95F4\u7684\u7834\u788E\u5C9B\u94FE\uFF0C\u76F8\u4F20\u662F\u53E4\u65F6\u8FDE\u63A5\u4E24\u5757\u5927\u9646\u7684\u9646\u6865\u201C\u591A\u6069\u4E4B\u81C2\u201D\u7684\u6B8B\u4F59\u3002\u8FD9\u91CC\u957F\u671F\u662F\u6D77\u76D7\u7684\u5DE2\u7A74\u548C\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u4E89\u593A\u7684\u6218\u573A\uFF0C\u4E5D\u94DC\u677F\u738B\u4E4B\u6218\u4E5F\u5728\u6B64\u8FDB\u884C\u3002"},refs:["agot","twoiaf","maps"],confidence:"high"},{id:"bloodstone",kind:"island",region:"free-cities",at:[737,1190],rank:2,names:{en:"Bloodstone",zh:"\u8840\u77F3\u5C9B"},summary:{en:"One of the larger islands of the Stepstones, fought over in the wars between Prince Daemon Targaryen and the Triarchy, and again in later struggles for the islands.",zh:"\u77F3\u9636\u5217\u5C9B\u4E2D\u8F83\u5927\u7684\u5C9B\u5C7F\u4E4B\u4E00\uFF0C\u6234\u8499\xB7\u5766\u683C\u5229\u5B89\u738B\u5B50\u4E0E\u4E09\u5973\u513F\u8054\u76DF\u4EA4\u6218\u65F6\u66FE\u4E3A\u4E89\u593A\u7126\u70B9\uFF0C\u540E\u6765\u7FA4\u5C9B\u7684\u5386\u6B21\u4E89\u6597\u4E2D\u4E5F\u5C61\u906D\u6218\u706B\u3002"},refs:["twoiaf"],confidence:"medium"},{id:"grey-gallows",kind:"island",region:"free-cities",at:[770,1176],rank:1,names:{en:"Grey Gallows",zh:"\u7070\u8272\u7EDE\u67B6\u5C9B"},summary:{en:"An island of the Stepstones named in the histories of the wars fought over the chain. Its position here is approximate.",zh:"\u77F3\u9636\u5217\u5C9B\u4E2D\u7684\u4E00\u5EA7\u5C9B\u5C7F\uFF0C\u89C1\u4E8E\u56F4\u7ED5\u7FA4\u5C9B\u6240\u53D1\u751F\u7684\u6218\u4E89\u53F2\u8F7D\u3002\u6B64\u5904\u4F4D\u7F6E\u4E3A\u5927\u81F4\u63A8\u6D4B\u3002"},refs:["twoiaf"],confidence:"low"},{id:"torturers-deep",kind:"bay",region:"free-cities",at:[748,1206],rank:1,names:{en:"Torturer's Deep",zh:"\u62F7\u95EE\u8005\u6DF1\u6E0A"},summary:{en:"A deep channel among the Stepstones, one of the passages ships must thread between the islands. Its exact position is approximate.",zh:"\u77F3\u9636\u5217\u5C9B\u95F4\u7684\u4E00\u6761\u6DF1\u6C34\u822A\u9053\uFF0C\u662F\u8239\u53EA\u7A7F\u884C\u7FA4\u5C9B\u65F6\u5FC5\u7ECF\u7684\u6C34\u9053\u4E4B\u4E00\u3002\u5177\u4F53\u4F4D\u7F6E\u4E3A\u5927\u81F4\u63A8\u6D4B\u3002"},refs:["twoiaf"],confidence:"low"}]};export{e as default};
